   685→fun try_stop_borrow_deleverage<MarketType, DebtType>(market_id: &mut UID, emode_group_id: u8, emode_group: &EModeGroup, debt_type: TypeName) {
   686→    let total_borrow = emode_group.borrow_amount(debt_type).floor();
   687→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(market_id, ADLRegistryKey {});
   688→    adl.try_stop_borrow_deleverage<DebtType>(type_name::with_defining_ids<MarketType>(), emode_group_id, total_borrow);
