  1076→public struct LiquidationParams has drop {
  1077→    liquidation_ltv_threshold_override: Option<Decimal>,
  1078→    liquidation_incentive: Decimal,
  1079→    liquidation_revenue_factor: Decimal,
  1080→    close_factor: Decimal,
  1081→    // close factor will not be enforce if the debt being liquidated has usd value less or equal to this value
  1082→    close_factor_bypass_min_value: u64,
  1083→}
  1084→
  1085→// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
  1086→fun collaterals_usd_for_liquidation<MarketType>(
  1087→    emode_group: &EModeGroup,
  1088→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1089→
  1090→    obligation: &Obligation<MarketType>,
  1091→
  1092→    coin_decimals_registry: &CoinDecimalsRegistry,
  1093→    x_oracle: &XOracle,
  1094→    clock: &Clock,
  1095→): (Decimal, Decimal) {
  1096→    let mut total_weighted_usd = float::zero();
  1097→    let mut total_collateral_usd = float::zero();
  1098→
  1099→    let mut deposit_types = obligation.deposit_types();
  1100→    let oracle_base_token = emode_group.get_oracle_base_token();
  1101→
  1102→    while (!deposit_types.is_empty()) {
  1103→        let deposit_type = deposit_types.pop_back();
  1104→
  1105→        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();
  1106→        // cannot be collateral, ignore
  1107→        if (!collateral_config.can_be_collateral()) { continue };
  1108→        
  1109→        let weight = collateral_config.liquidation_factor();
  1110→
  1111→        let ctoken_amount = obligation.ctoken_amount_by_coin<MarketType>(deposit_type);
  1112→        let reserve = reserves.load_by_type<Reserve<MarketType>>(deposit_type);
  1113→        let collateral_amount = reserve.exchange_rate().mul(float::from(ctoken_amount));
  1114→
  1115→        let coin_price = get_price(x_oracle, deposit_type, oracle_base_token, clock);
  1116→        let decimals = coin_decimals_registry.decimals(deposit_type);
  1117→        
  1118→        let collateral_value_usd = coin_value(coin_price, collateral_amount, decimals);
  1119→        let collateral_weighted_usd = collateral_value_usd.mul(weight);
  1120→
  1121→        total_collateral_usd = total_collateral_usd.add(collateral_value_usd);
  1122→        total_weighted_usd = total_weighted_usd.add(collateral_weighted_usd);
  1123→    };
  1124→
  1125→    (total_weighted_usd, total_collateral_usd)
  1126→}
  1127→
  1128→/// Calculates the debts in usd against latest oracle ema price, without including the borrow weights
  1129→fun debts_value_usd_for_liquidation<MarketType>(
  1130→    emode_group: &EModeGroup,
  1131→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1132→
  1133→    obligation: &Obligation<MarketType>,
  1134→
  1135→    coin_decimals_registry: &CoinDecimalsRegistry,
  1136→
  1137→    x_oracle: &XOracle,
  1138→    clock: &Clock,
  1139→): (Decimal, Decimal) {
  1140→    let mut total_weighted_value_usd = float::zero();
  1141→    let mut total_value_usd = float::zero();
  1142→
  1143→    let debt_types = obligation.debt_types();
  1144→    let (mut i, n) = (0, debt_types.length());
  1145→
  1146→    let oracle_base_token = emode_group.get_oracle_base_token();
  1147→
  1148→    while (i < n) {
  1149→        let debt_type = *debt_types.borrow(i);
  1150→
  1151→        let reserve = reserves.load_by_type(debt_type);
  1152→
  1153→        let debt_amount = obligation.debt(debt_type).debt(reserve.borrow_index().value());
  1154→        let decimals = coin_decimals_registry.decimals(debt_type);
  1155→        let coin_price = get_price(x_oracle, debt_type, oracle_base_token, clock);
  1156→
  1157→        let coin_value_usd = coin_value(coin_price, debt_amount, decimals);
  1158→        total_value_usd = total_value_usd.add(coin_value_usd);
  1159→
  1160→        let borrow_weight = emode_group.borrow_emode(debt_type).borrow().borrow_weight();
  1161→        total_weighted_value_usd = total_weighted_value_usd.add(coin_value_usd.mul(borrow_weight));
  1162→
  1163→        i = i + 1;
  1164→    };
  1165→
  1166→    (total_weighted_value_usd, total_value_usd)
  1167→}
  1168→
  1169→/// Calculates the debts in usd against latest oracle price. Returns the total usd value then the borrow_weight weighted usd value
  1170→fun debts_value_usd_non_liquidation<MarketType>(
  1171→    emode_group: &EModeGroup,
  1172→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1173→    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,
  1174→
  1175→    obligation: &Obligation<MarketType>,
  1176→
  1177→    coin_decimals_registry: &CoinDecimalsRegistry,
  1178→
  1179→    x_oracle: &XOracle,
  1180→    clock: &Clock,
  1181→): Decimal {
  1182→    let mut total_weighted_value_usd = float::zero();
  1183→
  1184→    let debt_types = obligation.debt_types();
  1185→    let (mut i, n) = (0, debt_types.length());
  1186→
  1187→    let oracle_base_token = emode_group.get_oracle_base_token();
  1188→
  1189→    while (i < n) {
  1190→        let debt_type = *debt_types.borrow(i);
  1191→
  1192→        let reserve = reserves.load_by_type(debt_type);
  1193→
  1194→        let debt_amount = obligation.debt(debt_type).debt(reserve.borrow_index().value());
  1195→        let decimals = coin_decimals_registry.decimals(debt_type);
  1196→
  1197→        let tolerance = ema_spot_tolerance.load_by_type(debt_type);
  1198→        let coin_price = get_price_with_check(x_oracle, debt_type, oracle_base_token, clock, *tolerance);
  1199→
  1200→        let coin_value_usd = coin_value(coin_price, debt_amount, decimals);
  1201→
  1202→        let borrow_weight = emode_group.borrow_emode(debt_type).borrow().borrow_weight();
  1203→        total_weighted_value_usd = total_weighted_value_usd.add(coin_value_usd.mul(borrow_weight));
  1204→
  1205→        i = i + 1;
  1206→    };
  1207→
  1208→    total_weighted_value_usd
  1209→}
  1210→
  1211→/// Checks if the obligation is safe from liquidation based on current obligation freshness. If the obligation data is not
  1212→/// latest, the result could be delayed. This could be acceptable in some cases, but for liquidation, called should refresh
  1213→/// obligation to latest state!
  1214→fun is_obligation_safe<MarketType>(
  1215→    emode_group: &EModeGroup,
  1216→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1217→    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,
  1218→
  1219→    obligation: &Obligation<MarketType>,
  1220→
  1221→    coin_decimals_registry: &CoinDecimalsRegistry,
  1222→    x_oracle: &XOracle,
  1223→    clock: &Clock,
  1224→): bool {
  1225→    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
  1226→    let borrow_weight_weighted_debt_value = debts_value_usd_non_liquidation(
  1227→        emode_group,
  1228→        reserves,
  1229→        ema_spot_tolerance,
  1230→
  1231→        obligation,
  1232→        coin_decimals_registry,
  1233→        x_oracle,
  1234→        clock,
  1235→    );
  1236→
  1237→    let (collateral_weighted_value, _) = collaterals_usd_non_liquidation(
  1238→        emode_group,
  1239→        reserves,
  1240→        ema_spot_tolerance,
  1241→        obligation,
  1242→        coin_decimals_registry,
  1243→        x_oracle,
  1244→        clock,
  1245→    );
  1246→
  1247→    // NOTE: if collaterals_value == borrow_weight_weighted_debt_value, this is still safe, the boundary of safety
  1248→    collateral_weighted_value.ge(borrow_weight_weighted_debt_value)
  1249→}
  1250→
  1251→// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
  1252→fun collaterals_usd_non_liquidation<MarketType>(
  1253→    emode_group: &EModeGroup,
  1254→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1255→    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,
  1256→
  1257→    obligation: &Obligation<MarketType>,
  1258→
  1259→    coin_decimals_registry: &CoinDecimalsRegistry,
  1260→    x_oracle: &XOracle,
  1261→    clock: &Clock,
  1262→): (Decimal, Decimal) {
  1263→    let mut total_weighted_usd = float::zero();
  1264→    let mut total_collateral_usd = float::zero();
  1265→
  1266→    let mut deposit_types = obligation.deposit_types();
  1267→
  1268→    let oracle_base_token = emode_group.get_oracle_base_token();
  1269→
  1270→    while (!deposit_types.is_empty()) {
  1271→        let deposit_type = deposit_types.pop_back();
  1272→
  1273→        let ctoken_amount = obligation.ctoken_amount_by_coin<MarketType>(deposit_type);
  1274→        let reserve = reserves.load_by_type<Reserve<MarketType>>(deposit_type);
  1275→        let collateral_amount = reserve.exchange_rate().mul(float::from(ctoken_amount));
  1276→
  1277→        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();
  1278→
  1279→        // cannot be collateral, ignore
  1280→        if (!collateral_config.can_be_collateral()) { continue };
  1281→        let collateral_factor = collateral_config.collateral_factor();
  1282→
  1283→        let tolerance = ema_spot_tolerance.load_by_type(deposit_type);
  1284→        let coin_price = get_price_with_check(x_oracle, deposit_type, oracle_base_token, clock, *tolerance);
  1285→
  1286→        let decimals = coin_decimals_registry.decimals(deposit_type);
  1287→        
  1288→        let collateral_value_usd = coin_value(coin_price, collateral_amount, decimals);
  1289→        let collateral_weighted_usd = collateral_value_usd.mul(collateral_factor);
  1290→
  1291→        total_collateral_usd = total_collateral_usd.add(collateral_value_usd);
  1292→        total_weighted_usd = total_weighted_usd.add(collateral_weighted_usd);
  1293→    };
  1294→
  1295→    (total_weighted_usd, total_collateral_usd)
  1296→}
  1297→
  1298→#[test_only]
