   818→}
   819→
   820→public(package) fun repay_flash_loan<MarketType, CoinType>(
   821→    self: &mut Market<MarketType>,
   822→
   823→    mut coin: Coin<CoinType>,
   824→    loan: FlashLoan<MarketType, CoinType>,
   825→
   826→    referral: &mut protocol::referral::Referral,
   827→    mut maybe_referral_code: Option<String>,
   828→
   829→    ctx: &mut TxContext
   830→) {
   831→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   832→
   833→    assert!(asset.flash_loan_ongoing(), error::flash_loan_not_ongoing());
   834→    asset.flash_loan_finished<MarketType>();
   835→
   836→    let FlashLoan { inner, fee } = loan;
   837→    assert!(coin.value() == inner.amount() + fee, error::reserve_flash_loan_not_paid_enough());
   838→
   839→    let mut fee_coin = coin.split(fee, ctx);
   840→
   841→    if (maybe_referral_code.is_some()) {
   842→        let referral_code = maybe_referral_code.extract();
   843→        fee_coin = referral.track_flash_loan_usage(
   844→            fee_coin,
   845→            referral_code,
   846→            ctx.sender(),
   847→            ctx,
